import { StructuredLogger } from '../logging/structured-logger';
import { forEachSequential } from '../common/async-sequence';
import {
  isAllowedTool,
  parseToolArgs,
} from './unified-agent-tool-parser.helpers';
import {
  executeToolAction,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';
import type { ActionEntry, ToolArgs } from './unified-agent.types';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';

type UnknownRecord = Record<string, unknown>;

interface ToolCallLike {
  type: string;
  function: {
    name: string;
    arguments?: string;
  };
}

export async function processUnifiedAgentToolCalls(
  deps: {
    logger: StructuredLogger;
    actions: UnifiedAgentActionsService;
    toolRouterDeps: Omit<ExecuteToolActionDeps, 'logger' | 'actions'>;
  },
  params: {
    workspaceId: string;
    contactId: string;
    phone: string;
    allowedTools?: string[];
    executeTools: boolean;
    context?: UnknownRecord;
    toolCalls: ToolCallLike[];
  },
): Promise<ActionEntry[]> {
  const actionsList: ActionEntry[] = [];

  if (!params.executeTools) {
    return actionsList;
  }

  await forEachSequential(params.toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, params.allowedTools)) {
      deps.logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${params.workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {} as ToolArgs, result: blockedResult });
      await deps.actions.logAutopilotEvent(
        params.workspaceId,
        params.contactId,
        toolName,
        {} as ToolArgs,
        blockedResult,
      );
      return;
    }
    const toolArgs = parseToolArgs(toolCall.function.arguments);
    if (!toolCall.function.arguments) {
      /* parsed fine */
    } else if (toolCall.function.arguments !== '{}') {
      try {
        JSON.parse(toolCall.function.arguments);
      } catch {
        deps.logger.warn(`Failed to parse tool args for ${toolName}`);
      }
    }
    const result = await executeToolAction(
      { logger: deps.logger, actions: deps.actions, ...deps.toolRouterDeps },
      params.workspaceId,
      params.contactId,
      params.phone,
      toolName,
      toolArgs as ToolArgs,
      params.context,
    );
    actionsList.push({ tool: toolName, args: toolArgs as ToolArgs, result });
    await deps.actions.logAutopilotEvent(
      params.workspaceId,
      params.contactId,
      toolName,
      toolArgs as ToolArgs,
      result,
    );
  });

  return actionsList;
}

import type { StructuredLogger } from '../logging/structured-logger';
import {
  buildPredecidedActionDraft,
  executePredecidedAgentActions,
} from './unified-agent-predecided-actions.part';
import {
  executeToolAction,
  num,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';
import {
  recordAgentRuntimeTurn,
} from './unified-agent-runtime.helpers';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { AgentRuntimeContextService } from './agent-runtime';
import OpenAI from 'openai';

type UnknownRecord = Record<string, unknown>;

export interface ProcessPredecidedActionsDeps {
  logger: StructuredLogger;
  actions: UnifiedAgentActionsService;
  response: UnifiedAgentResponseService;
  agentRuntime?: AgentRuntimeContextService;
  toolRouterDeps: Omit<ExecuteToolActionDeps, 'logger' | 'actions'>;
  responseDeps: {
    openai: OpenAI | null;
    writerModel: string;
    fallbackWriterModel: string;
  };
}

export async function processUnifiedAgentPredecidedActions(
  deps: ProcessPredecidedActionsDeps,
  params: {
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    allowedTools?: string[];
    predecidedActions: PredecidedAction[];
    context?: UnknownRecord;
    channel: string;
    conversationHistoryLength: number;
  },
): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const actionsList = await executePredecidedAgentActions({
    ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
    contactId: params.contactId,
    ...(params.context !== undefined ? { context: params.context } : {}),
    executeTool: (wsId, cId, ph, tool, args, ctx) =>
      executeToolAction(
        { logger: deps.logger, actions: deps.actions, ...deps.toolRouterDeps },
        wsId,
        cId,
        ph,
        tool,
        args,
        ctx,
      ),
    logAutopilotEvent: deps.actions.logAutopilotEvent.bind(deps.actions),
    phone: params.phone,
    predecidedActions: params.predecidedActions,
    workspaceId: params.workspaceId,
  });

  const intent = deps.response.extractIntent(actionsList, params.message);
  const draftedReply = await deps.response.composeWriterReply(
    deps.responseDeps.openai,
    deps.responseDeps.writerModel,
    deps.responseDeps.fallbackWriterModel,
    {
      workspaceId: params.workspaceId,
      customerMessage: params.message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: params.conversationHistoryLength,
    },
  );

  await recordAgentRuntimeTurn(deps.agentRuntime, {
    workspaceId: params.workspaceId,
    channel: params.channel,
    userMessage: params.message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId: params.contactId,
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: true,
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

