import type OpenAI from 'openai';
import type { ChatCompletionMessageParam } from 'openai/resources/chat';
import { StructuredLogger } from '../logging/structured-logger';
import { PlanLimitsService } from '../billing/plan-limits.service';
import { PrismaService } from '../prisma/prisma.service';
import { chatCompletionWithFallback } from './openai-wrapper';
import { UnifiedAgentContextService } from './unified-agent-context.service';
import { UnifiedAgentResponseService } from './unified-agent-response.service';
import { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { AgentRuntimeContextService } from './agent-runtime';
import type { AbiBuilderService } from './abi/abi-builder.service';
import type { RiskGateService } from './risk-class/risk-gate.service';
import { formatPromptValue } from './unified-agent-tool-parser.helpers';
import {
  buildAgentRuntimeContext,
  recordAgentRuntimeTurn,
} from './unified-agent-runtime.helpers';
import { buildUnifiedAgentCognitiveState } from './unified-agent-cognitive-state.helpers';
import {
  executeToolAction,
  actionSucceeded,
  type ExecuteToolActionDeps,
} from './unified-agent-tool-router.helpers';
import { processUnifiedAgentToolCalls } from './unified-agent-tool-call-processing.helpers';
import {
  processUnifiedAgentPredecidedActions,
} from './unified-agent-predecided-processing.helpers';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import type { AuditService } from '../audit/audit.service';

type UnknownRecord = Record<string, unknown>;

const UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED =
  'Primary LLM configuration is required for unified agent generation';

export interface ProcessIncomingMessageDeps {
  logger: StructuredLogger;
  prisma: PrismaService;
  planLimits: PlanLimitsService;
  auditService: AuditService;
  ctx: UnifiedAgentContextService;
  response: UnifiedAgentResponseService;
  actions: UnifiedAgentActionsService;
  agentRuntime?: AgentRuntimeContextService;
  abiBuilder?: AbiBuilderService;
  riskGate?: RiskGateService;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
  writerModel: string;
  fallbackWriterModel: string;
}

export async function processIncomingUnifiedAgentMessage(
  deps: ProcessIncomingMessageDeps,
  params: {
    allowedTools?: string[];
    predecidedActions?: PredecidedAction[];
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
  },
): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const { workspaceId, contactId, phone, message, context } = params;
  const predecidedActions = params.predecidedActions ?? [];

  if (!deps.openai && predecidedActions.length === 0) {
    deps.logger.warn('OpenAI not configured');
    return deps.response.buildFallbackResult(message);
  }

  const [workspace, contact, conversationHistory, products] = await Promise.all([
    deps.ctx.getWorkspaceContext(workspaceId),
    deps.ctx.getContactContext(workspaceId, contactId, phone),
    deps.ctx.getConversationHistory(workspaceId, contactId, 0, phone),
    deps.ctx.getProducts(workspaceId),
  ]);

  const productIds = products
    .map((product: UnknownRecord) => {
      const productValue = deps.ctx.readRecord(product.value);
      return deps.ctx.readOptionalText(productValue.id) || deps.ctx.readOptionalText(product.id);
    })
    .filter((productId): productId is string => Boolean(productId));
  let aiConfigs: UnknownRecord[] = [];
  if (productIds.length > 0) {
    try {
      aiConfigs = await deps.prisma.productAIConfig.findMany({
        take: 50,
        where: { productId: { in: productIds } },
        select: {
          id: true,
          productId: true,
          tone: true,
          persistenceLevel: true,
          messageLimit: true,
          customerProfile: true,
          positioning: true,
          objections: true,
          salesArguments: true,
        },
      });
    } catch {
      /* ProductAIConfig may not exist yet */
    }
  }

  const compressedContext = await deps.ctx.buildAndPersistCompressedContext(
    workspaceId,
    contactId,
    phone,
    contact,
  );
  const tacticalHint = deps.ctx.buildLeadTacticalHint({
    leadName: deps.ctx.isRecord(contact) ? deps.ctx.readText(contact.name).trim() : '',
    currentMessage: message,
    conversationHistory,
  });

  const channel = deps.ctx.readText(context?.channel, 'whatsapp');

  const agentRuntimeContext = await buildAgentRuntimeContext(deps.agentRuntime, {
    workspaceId,
    channel,
    message,
    contactId,
    ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
  });
  const systemPrompt = [
    deps.ctx.buildSystemPrompt(workspace, products, aiConfigs),
    agentRuntimeContext.systemPromptBlock,
  ].join('\n\n');
  const stylePolicy = deps.response.buildReplyStyleInstruction(
    message,
    conversationHistory.length,
  );
  const contactData: Record<string, unknown> = deps.ctx.isRecord(contact) ? contact : {};
  const contactName = deps.ctx.readText(contactData.name).trim() || phone;
  const contactSentiment = deps.ctx.readText(contactData.sentiment).trim() || 'NEUTRAL';
  const leadScore = deps.ctx.readText(contactData.leadScore, '0');
  const tagNames = deps.ctx.readTagList(contactData.tags);

  const additionalContext = context ? formatPromptValue(context) : '';
  const currentInput = {
    raw: message,
    channel,
    arrivalTimestamp: new Date().toISOString(),
  };

  const cognitiveState = await buildUnifiedAgentCognitiveState(
    { logger: deps.logger, abiBuilder: deps.abiBuilder },
    currentInput,
  );

  const messages: ChatCompletionMessageParam[] = [
    ...conversationHistory,
    {
      role: 'user',
      content: JSON.stringify({
        cognitiveState,
        runtimeContext: {
          workspaceProductContext: systemPrompt,
          compressedMemory: compressedContext || null,
          additionalContext,
          tacticalHint:
            tacticalHint || 'responder com clareza, valor concreto e próximo passo.',
          responsePolicy: stylePolicy,
        },
        contact: {
          name: contactName,
          sentiment: contactSentiment,
          leadScore,
          tags: tagNames,
        },
        currentInput,
      }),
    },
  ];

  const toolRouterDeps: Omit<ExecuteToolActionDeps, 'logger' | 'actions'> = {
    prisma: deps.prisma,
    auditService: deps.auditService,
    riskGate: deps.riskGate,
    agentRuntime: deps.agentRuntime,
    openai: deps.openai,
    primaryBrainModel: deps.primaryBrainModel,
    fallbackBrainModel: deps.fallbackBrainModel,
  };

  if (predecidedActions.length > 0) {
    return processUnifiedAgentPredecidedActions(
      {
        logger: deps.logger,
        actions: deps.actions,
        response: deps.response,
        agentRuntime: deps.agentRuntime,
        toolRouterDeps,
        responseDeps: {
          openai: deps.openai,
          writerModel: deps.writerModel,
          fallbackWriterModel: deps.fallbackWriterModel,
        },
      },
      {
        workspaceId,
        contactId,
        phone,
        message,
        allowedTools: params.allowedTools,
        predecidedActions,
        context,
        channel,
        conversationHistoryLength: conversationHistory.length,
      },
    );
  }

  let llmResponse: OpenAI.Chat.ChatCompletion;
  try {
    await deps.planLimits.ensureTokenBudget(params.workspaceId);
    const openai = deps.openai;
    if (!openai) {
      const error = new Error();
      error.message = UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED;
      throw error;
    }
    llmResponse = await chatCompletionWithFallback(
      openai,
      {
        model: deps.primaryBrainModel,
        messages,
        temperature: 0.82,
        top_p: 0.9,
      },
      deps.fallbackBrainModel,
    );
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : typeof err === 'string' ? err : 'unknown';
    deps.logger.error(`OpenAI agent processing failed, using fallback: ${msg}`);
    return deps.response.buildFallbackResult(message);
  }
  if (!llmResponse) {
    return deps.response.buildFallbackResult(message);
  }
  const firstChoice = llmResponse.choices[0];
  if (!firstChoice) {
    return deps.response.buildFallbackResult(message);
  }
  await deps.planLimits
    .trackAiUsage(params.workspaceId, llmResponse.usage?.total_tokens ?? 500)
    .catch(() => {});

  const assistantMessage = firstChoice.message;
  const executeTools = context?.executeTools !== false;

  let actionsList: ActionEntry[] = [];
  if (executeTools && assistantMessage.tool_calls && assistantMessage.tool_calls.length > 0) {
    actionsList = await processUnifiedAgentToolCalls(
      {
        logger: deps.logger,
        actions: deps.actions,
        toolRouterDeps,
      },
      {
        workspaceId,
        contactId,
        phone,
        allowedTools: params.allowedTools,
        executeTools,
        context,
        toolCalls: assistantMessage.tool_calls as unknown as Array<{
          type: string;
          function: { name: string; arguments?: string };
        }>,
      },
    );
  }

  const intent = deps.response.extractIntent(actionsList, message);
  const confidence = deps.response.calculateConfidence(actionsList, llmResponse);
  const draftedReply = await deps.response.composeWriterReply(
    deps.openai,
    deps.writerModel,
    deps.fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: assistantMessage.content,
      actions: actionsList,
      historyTurns: conversationHistory.length,
    },
  );

  await recordAgentRuntimeTurn(deps.agentRuntime, {
    workspaceId,
    channel,
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence,
  };
}

